// AGEN 1: Scanner & Narrative Evaluator (OpenRouter NEX-AGI / DeepSeek V4 Flash)
const response = $input.first().json;
const coin = Array.isArray(response) ? response[0] : (response.data ? response.data[0] : response);

if (!coin || !coin.mint) {
  return [];
}

const OPENROUTER_MODEL = 'nex-agi/nex-n2.5-pro:free';
const OPENROUTER_KEY = Buffer.from('c2stb3ItdjEtNzMwMmE3MjAwZjFiYTc3NmQxYWVkZjI5Yzc5M2JlNjNjOWM1ZDJiNmYzMmIwNDk4ZjI2OTc0ZDFjOWM3ZGJjMQ==', 'base64').toString('utf-8');
const ANYMODEL_MODEL = 'ds/deepseek-v4-flash';
const ANYMODEL_KEY = Buffer.from('c2stZGM5ZDRiN2RmMzZiYTU1NS1rN3BycGItOGIxYjk3Y2M=', 'base64').toString('utf-8');

// Fast blacklist check
const blacklistWords = ['presale', 'airdrop claim', 'free mint', 'send sol', 'honeypot'];
const fullText = `${coin.name || ''} ${coin.symbol || ''} ${coin.description || ''}`.toLowerCase();
let isBlacklisted = blacklistWords.some(w => fullText.includes(w));

let narrativeScore = 0.2;
let reasoning = 'Base meme score';
let matchedKeywords = [];
let aiModelUsed = OPENROUTER_MODEL;

if (!isBlacklisted) {
  try {
    const aiRes = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${OPENROUTER_KEY}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'http://localhost:3000',
        'X-Title': 'PumpFun Multi-Agent Bot'
      },
      body: JSON.stringify({
        model: OPENROUTER_MODEL,
        messages: [
          {
            role: 'system',
            content: 'You are Agen 1: Meme Token Narrative & Virality Evaluator on Solana pump.fun. Output JSON only: {\"narrative_score\": number 0.0-1.0, \"reasoning\": string, \"viral_hooks\": string[], \"is_blacklisted\": boolean}'
          },
          {
            role: 'user',
            content: `Token: "${coin.name}" ($${coin.symbol})\nDescription: "${coin.description || ''}"`
          }
        ],
        max_tokens: 150,
        temperature: 0.2
      }),
      signal: AbortSignal.timeout(6000)
    });

    if (aiRes.ok) {
      const data = await aiRes.json();
      const raw = data.choices?.[0]?.message?.content?.trim() || '';
      const match = raw.match(/\{[\s\S]*\}/);
      if (match) {
        const parsed = JSON.parse(match[0]);
        if (typeof parsed.narrative_score === 'number') {
          narrativeScore = Math.min(Math.max(parseFloat(parsed.narrative_score.toFixed(2)), 0.0), 1.0);
          reasoning = parsed.reasoning || reasoning;
          matchedKeywords = Array.isArray(parsed.viral_hooks) ? parsed.viral_hooks : [];
          if (parsed.is_blacklisted) isBlacklisted = true;
        }
      }
    } else {
      throw new Error('OpenRouter response not ok');
    }
  } catch (e) {
    try {
      const aiRes2 = await fetch('https://anymodel.org/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${ANYMODEL_KEY}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: ANYMODEL_MODEL,
          messages: [
            {
              role: 'system',
              content: 'You are Agen 1: Meme Token Narrative & Virality Evaluator on Solana pump.fun. Output JSON only: {\"narrative_score\": number 0.0-1.0, \"reasoning\": string, \"viral_hooks\": string[], \"is_blacklisted\": boolean}'
            },
            {
              role: 'user',
              content: `Token: "${coin.name}" ($${coin.symbol})\nDescription: "${coin.description || ''}"`
            }
          ],
          max_tokens: 150,
          temperature: 0.2
        }),
        signal: AbortSignal.timeout(6000)
      });
      if (aiRes2.ok) {
        const data2 = await aiRes2.json();
        const raw2 = data2.choices?.[0]?.message?.content?.trim() || '';
        const match2 = raw2.match(/\{[\s\S]*\}/);
        if (match2) {
          const parsed2 = JSON.parse(match2[0]);
          if (typeof parsed2.narrative_score === 'number') {
            narrativeScore = Math.min(Math.max(parseFloat(parsed2.narrative_score.toFixed(2)), 0.0), 1.0);
            reasoning = parsed2.reasoning || reasoning;
            matchedKeywords = Array.isArray(parsed2.viral_hooks) ? parsed2.viral_hooks : [];
            if (parsed2.is_blacklisted) isBlacklisted = true;
            aiModelUsed = ANYMODEL_MODEL;
          }
        }
      }
    } catch (e2) {
      const viralKeywords = {
        'ai': 0.35, 'agent': 0.35, 'autonomous': 0.25, 'gpt': 0.25, 'neural': 0.2,
        'quantum': 0.2, 'cyber': 0.2, 'doge': 0.25, 'elon': 0.25, 'trump': 0.2,
        'solana': 0.15, 'pepe': 0.25, 'cto': 0.2, 'terminal': 0.2
      };
      for (const [kw, weight] of Object.entries(viralKeywords)) {
        if (new RegExp(`\\b${kw}\\b`, 'i').test(fullText)) {
          narrativeScore += weight;
          matchedKeywords.push(kw);
        }
      }
      narrativeScore = Math.min(Math.max(parseFloat(narrativeScore.toFixed(2)), 0.0), 1.0);
      reasoning = 'Algorithmic heuristic fallback';
      aiModelUsed = 'heuristic-regex';
    }
  }
}

if (isBlacklisted) narrativeScore = 0.0;

return [{
  json: {
    tokenAddress: coin.mint,
    name: coin.name || 'Unknown',
    symbol: coin.symbol || 'TOKEN',
    description: coin.description || '',
    image_uri: coin.image_uri || '',
    creator: coin.creator || '',
    virtual_sol_reserves: coin.virtual_sol_reserves || 30000000000,
    virtual_token_reserves: coin.virtual_token_reserves || 1073000000000000,
    usd_market_cap: coin.usd_market_cap || 5000,
    narrative_score: narrativeScore,
    reasoning: reasoning,
    keywords: matchedKeywords,
    aiModel: aiModelUsed,
    scannedAt: new Date().toISOString()
  }
}];

// AGEN 2: Security & Kill-Vote Auditor (Claude Sonnet 4.6)
const rugcheckResp = $input.first().json;
const tokenData = $('Agen 1: Narrative Evaluator (DeepSeek V4 Flash)').first().json;

const AI_BASE_URL = 'https://anymodel.org/v1';
const MODEL_NAME = 'cc/claude-sonnet-4-6';
const API_KEY = 'sk-dc9d4b7df36ba555-fccapc-54bc2abb';

const reasons = [];
let mintAuthNull = true;
let freezeAuthNull = true;
let top5Percent = 0.0;

if (rugcheckResp && rugcheckResp.token) {
  if (rugcheckResp.token.mintAuthority !== null && rugcheckResp.token.mintAuthority !== undefined) {
    mintAuthNull = false;
    reasons.push(`Mint authority active: ${rugcheckResp.token.mintAuthority}`);
  }
  if (rugcheckResp.token.freezeAuthority !== null && rugcheckResp.token.freezeAuthority !== undefined) {
    freezeAuthNull = false;
    reasons.push(`Freeze authority active: ${rugcheckResp.token.freezeAuthority}`);
  }

  if (Array.isArray(rugcheckResp.topHolders)) {
    const nonCurveHolders = rugcheckResp.topHolders.slice(0, 5);
    top5Percent = nonCurveHolders.reduce((acc, h) => acc + (h.pct || 0), 0);
    if (top5Percent > 25.0) {
      reasons.push(`Top 5 holders own ${top5Percent.toFixed(1)}% supply (Max: 25%)`);
    }
  }

  if (Array.isArray(rugcheckResp.risks)) {
    for (const r of rugcheckResp.risks) {
      if (r.level === 'danger') {
        reasons.push(`Hazard detected: ${r.name}`);
      }
    }
  }
} else {
  mintAuthNull = true;
  freezeAuthNull = true;
}

let auditPassed = (mintAuthNull && freezeAuthNull && top5Percent <= 25.0 && reasons.length === 0);
let aiReasoning = auditPassed ? 'All contract security checks verified' : reasons.join('; ');
let riskScore = auditPassed ? 5 : 85;

// Call Claude Sonnet 4.6 for intelligent Kill-Vote consensus
try {
  const aiRes = await fetch(`${AI_BASE_URL}/chat/completions`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: MODEL_NAME,
      messages: [
        {
          role: 'system',
          content: 'You are Agen 2: Senior Smart Contract Security & Kill-Vote Auditor for pump.fun tokens. Output JSON only: {\"audit_passed\": boolean, \"reasoning\": string, \"risk_score\": number, \"kill_vote_reasons\": string[]}'
        },
        {
          role: 'user',
          content: `Token: $${tokenData.symbol} (${tokenData.tokenAddress})\nMint Revoked: ${mintAuthNull}\nFreeze Revoked: ${freezeAuthNull}\nTop 5 Holders %: ${top5Percent.toFixed(1)}%\nKnown Issues: ${JSON.stringify(reasons)}`
        }
      ],
      max_tokens: 150,
      temperature: 0.15
    }),
    signal: AbortSignal.timeout(6000)
  });

  if (aiRes.ok) {
    const data = await aiRes.json();
    const raw = data.choices?.[0]?.message?.content?.trim() || '';
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      if (typeof parsed.audit_passed === 'boolean') {
        auditPassed = parsed.audit_passed && mintAuthNull && freezeAuthNull;
        aiReasoning = parsed.reasoning || aiReasoning;
        riskScore = parsed.risk_score || riskScore;
      }
    }
  }
} catch (e) {
  // Algorithmic fallback
}

return [{
  json: {
    ...tokenData,
    audit_passed: auditPassed,
    audit_details: {
      mintAuthorityDisabled: mintAuthNull,
      freezeAuthorityDisabled: freezeAuthNull,
      top5HoldingPercent: top5Percent,
      reasons: reasons,
      riskScore: riskScore,
      aiReasoning: aiReasoning,
      aiModel: MODEL_NAME,
      verifiedAt: new Date().toISOString()
    }
  }
}];

// AGEN 3: Execution & Timing Strategy (Grok 4.6)
const tokenData = $input.first().json;

const AI_BASE_URL = 'https://anymodel.org/v1';
const MODEL_NAME = 'xai/grok-4.6';
const API_KEY = 'sk-dc9d4b7df36ba555-vsncqh-e4668ad3';

let buyAmountSol = 0.5;
let slippageBps = 500;
let executionNote = 'Jito MEV instant bundle routed';

try {
  const aiRes = await fetch(`${AI_BASE_URL}/chat/completions`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: MODEL_NAME,
      messages: [
        {
          role: 'system',
          content: 'You are Agen 3: Execution & Timing MEV Engine (Grok 4.6) for Solana pump.fun. Output JSON only: {\"approved\": boolean, \"slippage_bps\": integer, \"buy_amount_sol\": number, \"execution_note\": string}'
        },
        {
          role: 'user',
          content: `Token: $${tokenData.symbol} (${tokenData.tokenAddress})\nTarget Entry: 0.5 SOL\nDefault Slippage: 500 bps`
        }
      ],
      max_tokens: 150,
      temperature: 0.15
    }),
