    ...tokenData,
    buyAmountSol: buyAmountSol,
    slippageBps: slippageBps,
    executionNote: executionNote,
    aiExecutionModel: MODEL_NAME
  }
}];

// Initialize Active Position Context
const buyResponse = $input.first().json;
const token = $('Agen 3: Strategy & Sizing (Grok 4.6)').first().json;

const initialVirtualSol = Number(token.virtual_sol_reserves) / 1e9 || 30.0;
const initialVirtualToken = Number(token.virtual_token_reserves) / 1e6 || 1073000000;
const entryPriceSol = initialVirtualSol / initialVirtualToken;

return [{
  json: {
    tokenAddress: token.tokenAddress,
    symbol: token.symbol,
    name: token.name,
    buyAmountSol: buyResponse.buyAmountSol || token.buyAmountSol || 0.5,
    entryPriceSol: entryPriceSol,
    currentPriceSol: entryPriceSol,
    previousVirtualSol: initialVirtualSol,
    aiExecutionPlan: token.executionNote || 'Jito MEV instant bundle routed',
    openedAt: Date.now(),
    tickCount: 0,
    isWhaleDump: false,
    isExitTriggered: false,
    exitReason: 'NONE'
  }
}];

// AGEN 4: Autonomous Tracker & Whale Radar (Kimi K3)
const position = $input.first().json;
position.tickCount = (position.tickCount || 0) + 1;

const AI_BASE_URL = 'https://anymodel.org/v1';
const MODEL_NAME = 'kmc/k3';
const API_KEY = 'sk-dc9d4b7df36ba555-ngxwsx-b63f5cc3';

let liveCoin = null;
try {
  const res = await fetch(`https://frontend-api.pump.fun/coins/${position.tokenAddress}`, {
    headers: { 'Accept': 'application/json' },
    signal: AbortSignal.timeout(4000)
  });
  if (res.ok) {
    liveCoin = await res.json();
  }
} catch (e) {
  // Fallback to simulated bonding curve tick
}

const currentVirtualSol = liveCoin && liveCoin.virtual_sol_reserves 
  ? Number(liveCoin.virtual_sol_reserves) / 1e9 
  : position.previousVirtualSol * (1 + (Math.random() * 0.08 - 0.02));

const currentVirtualToken = liveCoin && liveCoin.virtual_token_reserves 
  ? Number(liveCoin.virtual_token_reserves) / 1e6 
  : 1073000000;

const currentPriceSol = currentVirtualSol / currentVirtualToken;

// Whale Dump Detection
const solDelta = currentVirtualSol - position.previousVirtualSol;
const solDeltaPercent = position.previousVirtualSol > 0 
  ? (solDelta / position.previousVirtualSol) * 100 
  : 0;

let isWhaleDump = solDeltaPercent <= -8.0 || solDelta <= -2.5;

// PnL & Multiplier
const pnlPercent = ((currentPriceSol - position.entryPriceSol) / position.entryPriceSol) * 100;
const gainMultiplier = parseFloat((currentPriceSol / position.entryPriceSol).toFixed(2));

// Evaluasi Kondisi Exit
const isTakeProfit = gainMultiplier >= 60.0;
const isStopLoss = pnlPercent <= -15.0;

// AI Whale Radar Analysis via Kimi K3
let aiSentiment = isWhaleDump ? 'EMERGENCY_DUMP' : (solDeltaPercent > 0.5 ? 'BULLISH' : 'NEUTRAL');
let aiNote = 'Kimi K3 tracking bonding curve liquidity';

if (isWhaleDump || position.tickCount % 5 === 0) {
  try {
    const aiRes = await fetch(`${AI_BASE_URL}/chat/completions`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${API_KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: MODEL_NAME,
        messages: [
          {
            role: 'system',
            content: 'You are Agen 4: Autonomous Tracker & Whale Radar (Kimi K3) for pump.fun tokens. Output JSON only: {\"sentiment\": \"BULLISH\"|\"NEUTRAL\"|\"BEARISH\"|\"EMERGENCY_DUMP\", \"analysis\": string, \"is_whale_dump\": boolean}'
          },
          {
            role: 'user',
            content: `Token: $${position.symbol}\nPnL: ${pnlPercent.toFixed(2)}% (${gainMultiplier}x)\nCurve Delta SOL: ${solDeltaPercent.toFixed(2)}%\nReserves: ${currentVirtualSol.toFixed(2)} SOL`
          }
        ],
        max_tokens: 150,
        temperature: 0.15
      }),
      signal: AbortSignal.timeout(5000)
    });

    if (aiRes.ok) {
      const data = await aiRes.json();
      const raw = data.choices?.[0]?.message?.content?.trim() || '';
      const match = raw.match(/\{[\s\S]*\}/);
      if (match) {
        const parsed = JSON.parse(match[0]);
        if (parsed.sentiment) aiSentiment = parsed.sentiment;
        if (parsed.analysis) aiNote = parsed.analysis;
        if (parsed.is_whale_dump) isWhaleDump = true;
      }
    }
  } catch (e) {
    // Graceful fallback
  }
}

const isExitTriggered = isWhaleDump || isTakeProfit || isStopLoss;
let exitReason = 'NONE';
if (isWhaleDump) exitReason = 'WHALE_DUMP_EMERGENCY';
else if (isTakeProfit) exitReason = 'TAKE_PROFIT_60X';
else if (isStopLoss) exitReason = 'STOP_LOSS';

// Update state
position.previousVirtualSol = currentVirtualSol;
position.currentPriceSol = currentPriceSol;
position.gainMultiplier = gainMultiplier;
position.pnlPercent = parseFloat(pnlPercent.toFixed(2));
position.solDeltaPercent = parseFloat(solDeltaPercent.toFixed(2));
position.isWhaleDump = isWhaleDump;
position.isExitTriggered = isExitTriggered;
position.exitReason = exitReason;
position.aiTrackerSentiment = aiSentiment;
position.aiTrackerNote = aiNote;
position.aiTrackerModel = MODEL_NAME;
position.lastPolledAt = new Date().toISOString();

return [{ json: position }];

// AGEN 5: Risk Manager & Sell Engine Post-Mortem (Claude Opus 4.8)
