          content: `Token: $${trackerData.symbol}\nExit Reason: ${trackerData.exitReason}\nPnL: ${trackerData.pnlPercent}% (${trackerData.gainMultiplier}x)\nHold Ticks: ${trackerData.tickCount}\nCurve Delta SOL: ${trackerData.solDeltaPercent}%`
        }
