    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      if (parsed.exit_report) exitReport = parsed.exit_report;
      if (parsed.post_mortem) postMortem = parsed.post_mortem;
    }
  }
} catch (e) {
  // Default summary fallback
}

return [{
  json: {
    ...trackerData,
    aiExitReport: exitReport,
    aiPostMortem: postMortem,
    aiExitModel: MODEL_NAME,
    closedAt: new Date().toISOString()
  }
}];
